//! T35 / ADR-0016: pack the built-in sounds and profiles as `.spankpack` files.
//!
//!   cargo run --release -p gen-builtin-sounds [-- --out assets/sounds/builtin]
//!
//! Profiles, events and sound names come from `assets/sounds/elevenlabs.json` (the same file
//! `tools/elevenlabs-sounds.py` generates candidates from). Every sound is a recording in
//! `assets/sounds/source/` generated by the author with ElevenLabs Sound Effects
//! ([`RECORDED_LICENSE`]): mixed down to mono, peak-limited if needed and normalized by the import
//! pipeline (-16 LUFS, ≤ -1 dBTP). Running it again produces identical files.
//! `assets/sounds/SOUNDS_LICENSE.md` is rewritten too.

use serde::Deserialize;
use spank_core::EventKind;
use spank_pack::{Manifest, ManifestSound, Pack, PackEvent, write_pack};
use std::collections::BTreeMap;
use std::path::PathBuf;

const SPEC: &str = "assets/sounds/elevenlabs.json";
/// Where the recordings live (relative to the repo root).
const SOURCE_DIR: &str = "assets/sounds/source";
/// SPDX-style reference for the recordings (not CC0); explained in SOUNDS_LICENSE.md.
const RECORDED_LICENSE: &str = "LicenseRef-Spank-ElevenLabs";
/// Budget for the uncompressed built-in audio (ADR-0008, ADR-0016).
const BUDGET: usize = 8 * 1024 * 1024;

#[derive(Deserialize)]
struct Spec {
    profiles: Vec<ProfileSpec>,
    /// Recordings made outside the generator (picked by ear earlier) that profiles keep.
    kept_sounds: Vec<KeptSound>,
}

#[derive(Deserialize)]
struct ProfileSpec {
    id: String,
    zh: String,
    en: String,
    #[serde(default)]
    keep: BTreeMap<EventKind, Vec<String>>,
    sounds: Vec<SoundSpec>,
}

#[derive(Deserialize)]
struct SoundSpec {
    stem: String,
    event: EventKind,
    zh: String,
    en: String,
    prompt: String,
}

#[derive(Deserialize)]
struct KeptSound {
    stem: String,
    zh: String,
    en: String,
    file: String,
    what: String,
}

/// A recording to pack.
struct Recording {
    stem: String,
    zh: String,
    en: String,
    /// File in [`SOURCE_DIR`].
    file: String,
    what: String,
}

/// A profile with its event → stems mapping.
type ProfilePlan<'a> = (&'a ProfileSpec, BTreeMap<EventKind, Vec<String>>);

/// Every recording the profiles use, plus each profile's event → stems mapping.
fn plan(spec: &Spec) -> (Vec<Recording>, Vec<ProfilePlan<'_>>) {
    let mut recs: BTreeMap<String, Recording> = BTreeMap::new();
    let mut profiles = Vec::new();
    for p in &spec.profiles {
        let mut events = p.keep.clone();
        for s in &p.sounds {
            events.entry(s.event).or_default().push(s.stem.clone());
            recs.insert(
                s.stem.clone(),
                Recording {
                    stem: s.stem.clone(),
                    zh: s.zh.clone(),
                    en: s.en.clone(),
                    file: format!("{}.wav", s.stem),
                    what: format!("ElevenLabs Sound Effects: {}", s.prompt),
                },
            );
        }
        for stem in p.keep.values().flatten() {
            let k = spec
                .kept_sounds
                .iter()
                .find(|k| &k.stem == stem)
                .unwrap_or_else(|| panic!("{} keeps {stem}, which is not in kept_sounds", p.id));
            recs.insert(
                stem.clone(),
                Recording {
                    stem: k.stem.clone(),
                    zh: k.zh.clone(),
                    en: k.en.clone(),
                    file: k.file.clone(),
                    what: k.what.clone(),
                },
            );
        }
        profiles.push((p, events));
    }
    (recs.into_values().collect(), profiles)
}

/// Loudness the recordings should reach (the import target is -16 LUFS).
const RECORDED_MIN_LUFS: f64 = -16.5;
/// Never limit more than this: beyond it crackles start to sound squashed.
const MAX_LIMIT_DB: f32 = 12.0;

/// Decode, mix down to mono and normalize a recording. Crackly recordings hit the -1 dBTP ceiling
/// long before -16 LUFS, so their peaks are limited just enough to get there.
fn load_recording(r: &Recording) -> spank_audio::ImportedSound {
    let path = PathBuf::from(SOURCE_DIR).join(&r.file);
    let s = spank_audio::import_file(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let ch = s.channels as usize;
    let mono: Vec<f32> = s
        .samples
        .chunks(ch)
        .map(|f| f.iter().sum::<f32>() / ch as f32)
        .collect();
    let normalize =
        |v: Vec<f32>| spank_audio::import::process(v, 1, s.sample_rate).expect("normalize recording");
    let mut db = 0.0;
    loop {
        let out = normalize(limit(&mono, db, s.sample_rate));
        if out.loudness_lufs >= RECORDED_MIN_LUFS || db >= MAX_LIMIT_DB {
            return out;
        }
        db += 1.0;
    }
}

/// Look-ahead peak limiter: peaks above `db` below the clip's own peak are pulled down to it.
/// The gain is the minimum required over a 5 ms look-ahead, smoothed over the same 5 ms (so it
/// reaches the needed reduction exactly at each peak) and released over 80 ms.
fn limit(x: &[f32], db: f32, rate: u32) -> Vec<f32> {
    if db <= 0.0 {
        return x.to_vec();
    }
    let peak = x.iter().fold(0.0f32, |m, v| m.max(v.abs())).max(1e-9);
    let threshold = peak * 10f32.powf(-db / 20.0);
    let look = (rate as f32 * 0.005) as usize;
    let release = (-1.0 / (rate as f32 * 0.08)).exp();
    let need: Vec<f32> = x
        .iter()
        .map(|v| (threshold / v.abs().max(1e-9)).min(1.0))
        .collect();
    // Minimum over [i, i + look].
    let min_ahead: Vec<f32> = (0..x.len())
        .map(|i| {
            need[i..(i + look + 1).min(x.len())]
                .iter()
                .fold(1.0f32, |m, &g| m.min(g))
        })
        .collect();
    let width = (look + 1) as f32;
    let mut out = Vec::with_capacity(x.len());
    // Running sum of min_ahead over [i - look, i]; samples before the start count as 1.
    let (mut sum, mut env) = (width, 1.0f32);
    for (i, &v) in x.iter().enumerate() {
        sum += min_ahead[i] - if i > look { min_ahead[i - look - 1] } else { 1.0 };
        let g = (sum / width).min(1.0);
        env = if g < env { g } else { g + (env - g) * release };
        out.push(v * env);
    }
    out
}

fn sha256_hex(b: &[u8]) -> String {
    use sha2::Digest;
    sha2::Sha256::digest(b)
        .iter()
        .map(|x| format!("{x:02x}"))
        .collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let out: PathBuf = args
        .iter()
        .position(|a| a == "--out")
        .and_then(|i| args.get(i + 1))
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("assets/sounds/builtin"));
    std::fs::create_dir_all(&out).expect("create output dir");

    let spec: Spec = serde_json::from_slice(&std::fs::read(SPEC).expect("read spec")).expect("parse spec");
    let (recs, profiles) = plan(&spec);

    let mut wavs: BTreeMap<&str, (Vec<u8>, u32)> = BTreeMap::new();
    let mut audio_total = 0;
    for r in &recs {
        let processed = load_recording(r);
        let bytes = spank_audio::encode_wav(&processed);
        println!(
            "{:<17} {:>5} ms  {:>6.1} LUFS  {:>5.1} dBTP  {:>4} KB",
            r.stem,
            processed.duration_ms(),
            processed.loudness_lufs,
            processed.true_peak_dbtp,
            bytes.len() / 1024
        );
        audio_total += bytes.len();
        wavs.insert(&r.stem, (bytes, processed.duration_ms()));
    }
    println!("audio {} KB (budget {} KB)", audio_total / 1024, BUDGET / 1024);
    assert!(
        audio_total < BUDGET,
        "built-in sounds must stay under the ADR-0016 budget"
    );

    for (p, events) in &profiles {
        let used: Vec<&str> = {
            let mut v: Vec<&str> = events.values().flatten().map(String::as_str).collect();
            v.sort();
            v.dedup();
            v
        };
        let file = |stem: &str| format!("sounds/{stem}.wav");
        let manifest = Manifest {
            schema_version: spank_pack::SCHEMA_VERSION,
            id: format!("dev.spank.builtin.{}", p.id),
            name: BTreeMap::from([("zh-Hant".into(), p.zh.clone()), ("en".into(), p.en.clone())]),
            version: "2.0.0".into(),
            author: Some("kaija (generated with ElevenLabs Sound Effects)".into()),
            license: RECORDED_LICENSE.into(),
            sounds: used
                .iter()
                .map(|stem| {
                    let (bytes, ms) = &wavs[stem];
                    ManifestSound {
                        file: file(stem),
                        sha256: sha256_hex(bytes),
                        duration_ms: *ms,
                        suggested_events: events
                            .iter()
                            .filter(|(_, s)| s.iter().any(|x| x == stem))
                            .map(|(k, _)| PackEvent(*k))
                            .collect(),
                        license: Some(RECORDED_LICENSE.to_owned()),
                        source_url: None,
                    }
                })
                .collect(),
            profile: Some(
                events
                    .iter()
                    .map(|(k, s)| (PackEvent(*k), s.iter().map(|x| file(x)).collect()))
                    .collect(),
            ),
        };
        let pack = Pack {
            manifest,
            sounds: used.iter().map(|s| (file(s), wavs[s].0.clone())).collect(),
            icon: None,
        };
        let path = out.join(format!("{}.spankpack", p.id));
        write_pack(std::fs::File::create(&path).expect("create pack"), &pack).expect("write pack");
        // Read it back through the validating reader, as the app will.
        spank_pack::read_pack_file(&path).expect("pack validates");
        let size = std::fs::metadata(&path).unwrap().len();
        println!("→ {} ({} KB, {} sounds)", path.display(), size / 1024, used.len());
    }

    let mut md = format!(
        "# Built-in sounds\n\n\
         The built-in packs are built by `tools/gen-builtin-sounds` from `assets/sounds/elevenlabs.json`: \
         `cargo run --release -p gen-builtin-sounds` (the output is identical each time). \
         New candidates come from `python3 -I tools/elevenlabs-sounds.py` (ADR-0016).\n\n\
         ## License — `{RECORDED_LICENSE}`\n\n\
         Every built-in sound was generated by the project author (kaija) with \
         [ElevenLabs Sound Effects](https://elevenlabs.io/sound-effects) and is included in Spank with the \
         author's permission. They are **not** covered by CC0 or by the MIT license of the code: to use them \
         outside Spank, ask the author. Originals are in `assets/sounds/source/`; the packs hold mono, \
         -16 LUFS versions.\n\n\
         | File | 名稱 | Name | Source |\n|------|------|------|--------|\n"
    );
    for r in &recs {
        md.push_str(&format!(
            "| `{}.wav` | {} | {} | `source/{}` — {} |\n",
            r.stem, r.zh, r.en, r.file, r.what
        ));
    }
    md.push_str("\n| Profile | Pack |\n|---------|------|\n");
    for (p, _) in &profiles {
        md.push_str(&format!(
            "| {}（{}） | `builtin/{}.spankpack` |\n",
            p.zh, p.en, p.id
        ));
    }
    let license = out.parent().unwrap_or(&out).join("SOUNDS_LICENSE.md");
    std::fs::write(&license, md).expect("write license");
    println!("→ {}", license.display());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn limiter_caps_peaks_and_leaves_quiet_parts() {
        let rate = 48_000;
        // Quiet 0.1 tone with one 1.0 spike in the middle.
        let mut x: Vec<f32> = (0..rate).map(|i| 0.1 * (i as f32 * 0.05).sin()).collect();
        x[24_000] = 1.0;
        let y = limit(&x, 12.0, rate as u32);
        let cap = 10f32.powf(-12.0 / 20.0);
        assert!(
            y.iter().all(|v| v.abs() <= cap + 1e-4),
            "peak above the threshold"
        );
        assert!(
            (y[1000] - x[1000]).abs() < 1e-6,
            "far from the spike nothing changes"
        );
        assert_eq!(limit(&x, 0.0, rate as u32), x);
    }

    #[test]
    fn spec_covers_every_event_and_kept_sound() {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..").join(SPEC);
        let spec: Spec = serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
        let (recs, profiles) = plan(&spec);
        for (p, events) in &profiles {
            for k in EventKind::ALL {
                assert!(
                    events.get(&k).is_some_and(|s| !s.is_empty()),
                    "{} has no {k:?}",
                    p.id
                );
            }
        }
        let mut stems: Vec<_> = recs.iter().map(|r| &r.stem).collect();
        let n = stems.len();
        stems.dedup();
        assert_eq!(stems.len(), n, "sound stems are unique");
    }
}
